from rest_framework import serializers
from .models import Organization
from django.utils import timezone

class OrganizationSerializer(serializers.ModelSerializer):
    class Meta:
        model = Organization
        fields = ['name', 'founded_date', 'location', 'description']

    def validate_founded_date(self, value):
        if value > timezone.now().date():
            raise serializers.ValidationError("Founded date cannot be in the future")
        return value

    def validate_name(self, value):
        if Organization.objects.filter(name=value).exists():
            raise serializers.ValidationError("An organization with this name already exists")
        return value

    def validate(self, data):
        if 'founded_date' in data and 'name' in data:
            self.validate_founded_date(data['founded_date'])
            self.validate_name(data['name'])
        return data
```

