def count_unique_prime_factors(arr):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def prime_factors_count(num):
        count = 0
        for i in range(2, num + 1):
            if is_prime(i) and num % i == 0:
                count += 1
                while num % i == 0:
                    num //= i
        return count

    return [prime_factors_count(num) for num in arr]
```

