- `new(capacity: usize)`: Creates a new LRUCache instance with the specified capacity.
- `get(key: &K) -> Option<&V>`: Retrieves the value associated with the given key, updating its position in the cache to reflect its most recent use.
- `put(key: K, value: V)`: Inserts a new key-value pair into the cache. If the cache is at its maximum capacity, it should evict the least recently used item before inserting the new pair.

You should use the provided code snippet as a starting point and implement the necessary functionality to achieve the desired behavior.

```rust
use std::collections::HashMap;

struct LRUCache<K, V> {
    capacity: usize,
    cache: HashMap<K, V>,
    lru_order: Vec<K>,
}

impl<K: Eq + std::hash::Hash, V> LRUCache<K, V> {
    fn new(capacity: usize) -> LRUCache<K, V> {
        LRUCache {
            capacity,
            cache: HashMap::new(),
            lru_order: Vec::new(),
        }
    }

    fn get(&mut self, key: &K) -> Option<&V> {
        if let Some(&value) = self.cache.get(key) {
            self.update_lru_order(key);
            Some(&value)
        } else {
            None
        }
    }

    fn put(&mut self, key: K, value: V) {
        if self.cache.len() == self.capacity && !self.cache.contains_key(&key) {
            self.evict_lru();
        }
        self.cache.insert(key, value);
        self.update_lru_order(&key);
    }

    fn update_lru_order(&mut self, key: &K) {
        if let Some(index) = self.lru_order.iter().position(|k| k == key) {
            self.lru_order.remove(index);
        }
        self.lru_order.push(key.clone());
    }

    fn evict_lru(&mut self) {
        if let Some(oldest_key) = self.lru_order.first().cloned() {
            self.cache.remove(&oldest_key);
            self.lru_order.remove(0);
        }
    }
}

