        """Add a value to the list of values."""
        if not self.Config.case_sensitive:
            value = value.lower()
            self.values = [v.lower() for v in self.values]
        self.values.append(value)

    def remove_value(self, value: float) -> None:
        """Remove a value from the list of values if it exists."""
        if not self.Config.case_sensitive:
            value = value.lower()
            self.values = [v.lower() for v in self.values]
        if value in self.values:
            self.values.remove(value)

    def calculate_mean(self) -> float:
        """Calculate the mean of the values."""
        return sum(self.values) / len(self.values) if self.values else 0.0

    def calculate_median(self) -> float:
        """Calculate the median of the values."""
        sorted_values = sorted(self.values)
        n = len(sorted_values)
        if n % 2 == 0:
            return (sorted_values[n // 2 - 1] + sorted_values[n // 2]) / 2
        else:
            return sorted_values[n // 2]

    def calculate_range(self) -> float:
        """Calculate the range of the values."""
        return max(self.values) - min(self.values) if self.values else 0.0

    def set_domain(self, start: float, end: float) -> None:
        """Set the domain of the statistical variable."""
        self.domain = Interval(start, end)

    def is_within_domain(self, value: float) -> bool:
        """Check if a value is within the domain."""
        return self.domain.start <= value <= self.domain.end if self.domain else True
